def _primary_color_label(pixels, exclude_white: bool = False) -> tuple[str, str]:
    """




    """
    import numpy as _np
    arr = _np.asarray(pixels)
    flat = arr.flatten()
    if exclude_white:
        visible = flat[(flat >= 0) & (flat != 0)]
    else:
        visible = flat[flat >= 0]
    if visible.size == 0:
        return ("", "")
    values, counts = _np.unique(visible, return_counts=True)
    dominant = int(values[_np.argmax(counts)])
    entry = COLOR_PALETTE.get(dominant, {})
    return (entry.get("label", str(dominant)), entry.get("label_l2", str(dominant)))


def _label_for_sprite(spr) -> tuple[str, str, str]:
    """

















    """
    name = getattr(spr, "name", "")
    pixels = getattr(spr, "pixels", None)
    if name.startswith("robot_body-"):
        c_en, c_l2 = _primary_color_label(pixels) if pixels is not None else ("", "")
        return ("robot_body",
                f"Robot Body ({c_en})" if c_en else "Robot Body",
                f"({c_l2})" if c_l2 else "")
    if name.startswith("robot_leg-"):
        return ("robot_arm", "Robot Arm", "")
    if name == "goal-target":
        c_en, c_l2 = _primary_color_label(pixels) if pixels is not None else ("", "")
        return ("goal_target",
                f"Goal Target ({c_en})" if c_en else "Goal Target",
                f"({c_l2})" if c_l2 else "")
    if name.startswith("goal-"):
        c_en, c_l2 = _primary_color_label(pixels) if pixels is not None else ("", "")
        return ("goal",
                f"Goal ({c_en})" if c_en else "Goal",
                f"({c_l2})" if c_l2 else "")
    if name.startswith("decoration-"):

        c_en, c_l2 = _primary_color_label(pixels, exclude_white=True) if pixels is not None else ("", "")
        return ("robot_paint",
                f"Robot Paint ({c_en})" if c_en else "Robot Paint",
                f"({c_l2})" if c_l2 else "")
    if name.startswith("flash-robot_body"):
        return ("flash_robot_body", "Robot Body Flash", "")
    if name.startswith("flash-goal"):
        return ("flash_goal", "Goal Flash", "")
    return (name, name, name)


def _build_sprite_display_map() -> dict:
    """





    """
    return {name: _label_for_sprite(spr) for name, spr in sprites.items()}



SPRITE_DISPLAY: dict = _build_sprite_display_map()




