class RobotGroupData(TypedDict):
    """"""

    body: Sprite | None
    legs: list[Sprite]
    goal: Sprite | None


class GoalContactState(TypedDict):
    """"""

    goal: Sprite
    is_animating: bool
    contact_count: int
    anim_tick: int
    in_contact: bool
    flash_sprite: Sprite | None


class StepCounterDisplay(RenderableUserDisplay):
    """"""

    def __init__(self, max_steps: int):
        """"""
        self.max_steps = max_steps
        self.current_steps = max_steps

    def set_current_steps(self, n_steps: int) -> None:
        """"""
        self.current_steps = max(0, min(n_steps, self.max_steps))

    def render_interface(self, frame: np.ndarray) -> np.ndarray:
        """"""
        if self.max_steps == 0:
            return frame
        height = frame.shape[0]
        fill_ratio = self.current_steps / self.max_steps
        fill_height = round(height * fill_ratio)
        fill_height = min(fill_height, height)
        for y in range(height):
            if height - y <= fill_height:
                frame[y, 0] = 0
            else:
                frame[y, 0] = 5
        return frame


class ConnectionLineDisplay(RenderableUserDisplay):
    """"""

    def __init__(self, robot_groups: dict[str, RobotGroupData], camera: Camera, line_color: int = 1) -> None:
        """"""
        self.robot_groups = robot_groups
        self.camera = camera
        self.line_color = line_color

    def render_interface(self, frame: np.ndarray) -> np.ndarray:
        """"""
        scale, x_offset, y_offset = self.camera._calculate_scale_and_offset()
        for data in self.robot_groups.values():
            body_sprite = data.get("body")
            leg_sprites = data.get("legs", [])
            if not leg_sprites or not body_sprite:
                continue
            body_cx = (body_sprite.x + body_sprite.width // 2 - self.camera.x) * scale + x_offset
            body_cy = (body_sprite.y + body_sprite.height // 2 - self.camera.y) * scale + y_offset
            for leg in leg_sprites:
                leg_cx = (leg.x + leg.width // 2 - self.camera.x) * scale + x_offset
                leg_cy = (leg.y + leg.height // 2 - self.camera.y) * scale + y_offset
                self.draw_line(
                    frame,
                    leg_cx,
                    leg_cy,
                    body_cx,
                    body_cy,
                    self.line_color,
                )
        return frame

    def draw_line(
        self,
        frame: np.ndarray,
        x1: float,
        y1: float,
        x2: float,
        y2: float,
        color_key: int,
    ) -> None:
        """"""
        x1, y1, x2, y2 = (
            int(x1),
            int(y1),
            int(x2),
            int(y2),
        )
        dx = abs(x2 - x1)
        dy = abs(y2 - y1)
        sx = 1 if x1 < x2 else -1
        sy = 1 if y1 < y2 else -1
        err = dx - dy
        max_y, max_x = frame.shape
        while True:
            if 0 <= x1 < max_x and 0 <= y1 < max_y:
                pixel_val = frame[y1, x1]
                if pixel_val == 5 or pixel_val == 10:
                    frame[y1, x1] = color_key
            if x1 == x2 and y1 == y2:
                break
            e2 = err << 1
            if e2 > -dy:
                err -= dy
                x1 += sx
            if e2 < dx:
                err += dx
                y1 += sy


class R11l(ARCBaseGame):

    def __init__(self) -> None:
        self._step_counter_ui = StepCounterDisplay(max_steps=60)
        self._max_actions = 60
        cam = Camera(
            background=BACKGROUND_COLOR,
            letter_box=PADDING_COLOR,
            interfaces=[self._step_counter_ui],
        )
        self.selected_leg: Sprite | None = None
        self.selected_leg_idx: int = 0
        self.all_click_actions: list[ActionInput] = []
        for y in range(0, 64, 4):
            for x in range(0, 64, 4):
                action = ActionInput(id=GameAction.ACTION6.value, data={"x": x, "y": y})
                self.all_click_actions.append(action)
        self.robot_group_map: dict[str, RobotGroupData] = {}
        self.all_legs: list[Sprite] = []
        self.wall_sprites: list[Sprite] = []
        self.is_animating: bool = False
        self.anim_tick: int = 0
        self.anim_speed: int = 1
        self.anim_start_pos: tuple[int, int] = (0, 0)
        self.anim_end_pos: tuple[int, int] = (0, 0)
        self.bounce_back = False
        self.wall_hit_count: int = 0
        self.is_reversing: bool = False
        self.body_is_flashing: bool = False
        self.flash_count: int = 0
        self.flash_tick: int = 0
        self.flashing_body: Sprite | None = None
        self.body_flash_sprite: Sprite | None = None


        self._prev_body_flash_visible: bool = False
        self._prev_goal_flash_visible: dict[str, bool] = {}
        self.goal_contact_map: dict[str, GoalContactState] = {}
        self.goal_reached_map: dict[str, bool] = {}
        self.composite_body_map: dict[str, list[str]] = {}
        self.decoration_sprites: list[Sprite] = []





        self._log_state = ActionLogState()
        self.action_log:    list[str] = []
        self.action_log_l2: list[str] = []
        self._frame_sprite_log:     list[list[dict]] = []
        self._frame_nonsprite_log:  list[list[dict]] = []

        self._wall_hit_this_action:    int       = 0
        self._wall_hit_target_name:    str       = ""
        self._wall_hit_target_pos:     tuple[int, int, int, int] | None = None
        self._goal_contact_this_action: set[str] = set()
        self._goal_contact_pos:        dict[str, tuple[int, int, int, int]] = {}
        self._win_pending:             bool      = False
        self._gameover_pending:        bool      = False




        self._last_logged_action_count: int = 0
        super().__init__(game_id="r11l", levels=levels, camera=cam, available_actions=[6])

    def _get_hidden_state(self) -> np.ndarray:
        """"""
        state_arr = np.zeros((4, 4), dtype=np.int16)
        state_arr[0, 0] = int(self._action_count)
        return state_arr

    def strip_prefix(self, name: str, prefix: str) -> str | None:
        """"""
        if name.startswith(prefix):
            return name[len(prefix) :]
        return None

    def get_color_keys_in_level(self, level: Level) -> set[str]:
        """"""
        color_keys = set()
        for sprite in level.get_sprites():
            color_key = self.strip_prefix(sprite.name, "robot_body-")
            if color_key:
                color_keys.add(color_key)
            color_key = self.strip_prefix(sprite.name, "robot_leg-")
            if color_key:
                color_keys.add(color_key)
            color_key = self.strip_prefix(sprite.name, "goal-")
            if color_key:
                color_keys.add(color_key)
        return color_keys

    def on_set_level(self, level: Level) -> None:
        """"""
        color_keys = self.get_color_keys_in_level(level)
        self.robot_group_map = {}
        for color_key in color_keys:
            body_sprites = level.get_sprites_by_name(f"robot_body-{color_key}")
            leg_sprites = level.get_sprites_by_name(f"robot_leg-{color_key}")
            goal_sprites = level.get_sprites_by_name(f"goal-{color_key}")
            self.robot_group_map[color_key] = {
                "body": body_sprites[0] if body_sprites else None,
                "legs": leg_sprites,
                "goal": goal_sprites[0] if goal_sprites else None,
            }


        self.wall_sprites = [s for s in level.get_sprites() if s.name.startswith("background-")]
        self.all_legs = []
        for data in self.robot_group_map.values():
            self.all_legs.extend(data["legs"])
        self.is_animating = False
        self.anim_tick = 0
        self.is_reversing = False
        self.wall_hit_count = 0
        self.selected_leg_idx = 0
        self.body_is_flashing = False
        self.flash_count = 0
        self.flash_tick = 0
        self.flashing_body = None
        self.body_flash_sprite = None
        self._prev_body_flash_visible = False
        self._prev_goal_flash_visible = {}




        self.goal_contact_map = {}
        self.goal_reached_map = {}
        self.winning = False
        for color_key, data in self.robot_group_map.items():
            goal_sprite = data.get("goal")
            if goal_sprite:
                self.goal_contact_map[color_key] = {
                    "goal": goal_sprite,
                    "is_animating": False,
                    "contact_count": 0,
                    "anim_tick": 0,
                    "in_contact": False,
                    "flash_sprite": None,
                }
                self.goal_reached_map[color_key] = False
        self.composite_body_map = {}
        for color_key, data in self.robot_group_map.items():
            body = data["body"]
            if body and body.name.startswith("robot_body-black"):
                self.composite_body_map[body.name] = []
        self.decoration_sprites = [s for s in level.get_sprites() if s.name.startswith("decoration-")]
        for leg in self.all_legs:
            leg.color_remap(0, 3)
            leg._tags = []
            leg._tags.append("sys_click")
        if self.all_legs:
            self.all_legs.sort(key=lambda leg: (leg.x**2 + leg.y**2) ** 0.5)
            self.selected_leg_idx = 0
            self.select_leg(self.all_legs[self.selected_leg_idx])
        for color_key, data in self.robot_group_map.items():
            body = data["body"]
            legs = data["legs"]
            if body and len(legs) >= 2:
                self.center_body_on_legs(body, legs)
        remaining_actions = self._max_actions - self._action_count
        self._step_counter_ui.set_current_steps(remaining_actions)
        self.connection_display = ConnectionLineDisplay(self.robot_group_map, self.camera)
        self.camera.replace_interface([self._step_counter_ui, self.connection_display])





        _LAYOUT_PREFIX_ROLE: dict[str, str] = {
            "robot_body-":  "robot_body",
            "robot_leg-":   "robot_arm",
            "decoration-":  "robot_paint",
        }
        _layout_rows: list[dict] = []
        for _spr in self.current_level.get_sprites():
            if not _spr.is_visible:
                continue

            if _spr.name == "goal-target":
                _role = "goal_target"
            else:
                _role = None
                for _pref, _r in _LAYOUT_PREFIX_ROLE.items():
                    if _spr.name.startswith(_pref):
                        _role = _r
                        break
                if _role is None and _spr.name.startswith("goal-"):
                    _role = "goal"
            if _role is None:
                continue
            _, _le, _l2 = _label_for_sprite(_spr)
            _dx, _dy = self._to_display_xy(_spr.x, _spr.y)
            _arc = min(64 // self.camera.width, 64 // self.camera.height)
            _dw, _dh = _spr.width * _arc, _spr.height * _arc
            _layout_rows.append({
                "role":    _role,
                "role_en": _le,
                "role_l2": _l2,
                "sname":   _spr.name,
                "dx": _dx, "dy": _dy, "dw": _dw, "dh": _dh,
            })


        try:
            _ns_status = self.get_nonsprite_status() or []
        except Exception:
            _ns_status = []
        for _ns in _ns_status:
            if _ns.get("name") != "step_counter":
                continue
            _layout_rows.append({
                "role":    "remaining_step",
                "role_en": "Remaining Step Gauge",
                "role_l2": ''               ,
                "sname":   "step_counter",
                "dx": int(_ns.get("x", 0)),
                "dy": int(_ns.get("y", 0)),
                "dw": int(_ns.get("width", 0)),
                "dh": int(_ns.get("height", 0)),
            })

        if _layout_rows:
            self._set_event("initial_layout", _layout_rows)

    def _get_valid_actions(self) -> list[ActionInput]:
        """"""
        return self.all_click_actions

    def select_leg(self, leg: Sprite) -> None:
        """"""
        if self.selected_leg:
            self.selected_leg.color_remap(0, 3)
        leg.color_remap(3, 0)
        self.selected_leg = leg

    def center_body_on_legs(self, body: Sprite, legs: list[Sprite]) -> None:
        """"""
        if not legs or not body:
            return
        sum_cx = 0
        sum_cy = 0
        for leg in legs:
            leg_cx = leg.x + leg.width // 2
            leg_cy = leg.y + leg.height // 2
            sum_cx += leg_cx
            sum_cy += leg_cy
        avg_cx = sum_cx // len(legs)
        avg_cy = sum_cy // len(legs)
        new_x = avg_cx - body.width // 2
        new_y = avg_cy - body.height // 2
        body.set_position(new_x, new_y)

    def would_collide_with_wall(self, x: int, y: int) -> bool:
        """"""
        if not self.selected_leg:
            return False
        original_x = self.selected_leg.x
        original_y = self.selected_leg.y
        self.selected_leg.set_position(x, y)
        hit_wall = False
        for wall_spr in self.wall_sprites:
            if self.selected_leg.collides_with(wall_spr):
                hit_wall = True
                break
        self.selected_leg.set_position(original_x, original_y)
        return hit_wall

    def start_move_animation(self, target_x: int, target_y: int) -> None:
        """"""
        if self.selected_leg:
            self.is_animating = True
            self.anim_tick = 0
            self.is_reversing = False
            self.bounce_back = False
            self.anim_start_pos = (self.selected_leg.x, self.selected_leg.y)
            self.anim_end_pos = (target_x, target_y)

    def get_color_key_for_leg(self, leg: Sprite) -> str | None:
        """"""
        for color_key, data in self.robot_group_map.items():
            if leg in data["legs"]:
                return color_key
        return None

    def check_decoration_collisions(self) -> None:
        """"""
        for body_name in list(self.composite_body_map.keys()):
            body_sprites = self.current_level.get_sprites_by_name(body_name)
            if not body_sprites:
                continue
            body = body_sprites[0]
            for dec_sprite in self.decoration_sprites[:]:
                if body.collides_with(dec_sprite):










                    _before_colors = {int(c) for c in np.unique(body.pixels) if c != -1}
                    dec_pixels = dec_sprite.pixels
                    non_bg_mask = (dec_pixels != -1) & (dec_pixels != 0)
                    body.pixels[non_bg_mask] = dec_pixels[non_bg_mask]
                    self.composite_body_map[body_name].append(dec_sprite.name)
                    _after_colors = {int(c) for c in np.unique(body.pixels) if c != -1}
                    _removed = sorted(_before_colors - _after_colors)
                    _added   = sorted(_after_colors - _before_colors)
                    if _removed or _added:
                        def _name(c):
                            return COLOR_PALETTE.get(c, {}).get("label", str(c)).lower()
                        def _name_l2(c):
                            return COLOR_PALETTE.get(c, {}).get("label_l2", str(c))
                        bdx, bdy = self._to_display_xy(body.x, body.y)
                        _arc = min(64 // self.camera.width, 64 // self.camera.height)
                        bdw, bdh = body.width * _arc, body.height * _arc




                        _bt, _ble, _bl2 = self._display_for(body)
                        _dt, _dle, _dl2 = self._display_for(dec_sprite)

                        n_pair = min(len(_removed), len(_added))
                        for i in range(n_pair):
                            a, b = _removed[i], _added[i]
                            self._step_log.append(
                                f"[change]:[{_bt}]:[sname({body_name});position({bdx}_{bdy});bbox({bdw}_{bdh});color({_name(a)})_({_name(b)})]:{_ble} absorbs {_dle}; {_name(a)} is replaced by {_name(b)}.|The Object's color {_name(a)} is replaced by {_name(b)}."
                            )
                            self._step_log_l2.append(
                                f"[change]:[{_bt}]:[sname({body_name});position({bdx}_{bdy});bbox({bdw}_{bdh});color({_name(a)})_({_name(b)})]:{_bl2}{_dl2}{_name_l2(a)}{_name_l2(b)}|Object {_name_l2(a)}  {_name_l2(b)} "
                            )


                        for b in _added[n_pair:]:
                            self._step_log.append(
                                f"[change]:[{_bt}]:[sname({body_name});position({bdx}_{bdy});bbox({bdw}_{bdh});color(none)_({_name(b)})]:{_ble} absorbs {_dle} and gains color {_name(b)}.|The Object's color {_name(b)} is added."
                            )
                            self._step_log_l2.append(
                                f"[change]:[{_bt}]:[sname({body_name});position({bdx}_{bdy});bbox({bdw}_{bdh});color(none)_({_name(b)})]:{_bl2}{_dl2}{_name_l2(b)}|Object {_name_l2(b)} "
                            )

                        for a in _removed[n_pair:]:
                            self._step_log.append(
                                f"[change]:[{_bt}]:[sname({body_name});position({bdx}_{bdy});bbox({bdw}_{bdh});color({_name(a)})_(none)]:{_ble} loses color {_name(a)} after absorbing {_dle}.|The Object's color {_name(a)} is removed."
                            )
                            self._step_log_l2.append(
                                f"[change]:[{_bt}]:[sname({body_name});position({bdx}_{bdy});bbox({bdw}_{bdh});color({_name(a)})_(none)]:{_bl2}{_dl2}{_name_l2(a)}|Object {_name_l2(a)} "
                            )
                    self.current_level.remove_sprite(dec_sprite)
                    self.decoration_sprites.remove(dec_sprite)

    def colors_match(self, body: Sprite, goal_sprite: Sprite) -> bool:
        """"""
        body_colors = {int(c) for c in np.unique(body.pixels) if c > 0}
        if not body_colors:
            return False
        goal_colors = {int(c) for c in np.unique(goal_sprite.pixels) if c > 0}
        return body_colors == goal_colors

    def find_body_matching_goal(self, goal_sprite: Sprite) -> Sprite | None:
        """"""
        for body_name in self.composite_body_map.keys():
            body_sprites = self.current_level.get_sprites_by_name(body_name)
            if not body_sprites:
                continue
            body = body_sprites[0]
            if body.collides_with(goal_sprite) and self.colors_match(body, goal_sprite):
                return body
        return None

    def update_body_flash(self) -> None:
        """"""
        if not self.body_is_flashing or not self.flashing_body:
            return
        self.flash_tick += 1
        if self.flash_tick % 2 == 0:
            show_flash = self.flash_tick // 2 % 2 == 1
            if show_flash:
                if self.body_flash_sprite is None:
                    self.body_flash_sprite = sprites["flash-robot_body"].clone()
                    self.body_flash_sprite.set_position(self.flashing_body.x, self.flashing_body.y)
                    self.current_level.add_sprite(self.body_flash_sprite)
            elif self.body_flash_sprite is not None:
                self.current_level.remove_sprite(self.body_flash_sprite)
                self.body_flash_sprite = None
        if self.flash_tick % 4 == 0:
            self.flash_count += 1
            if self.flash_count >= 5:
                if self.body_flash_sprite is not None:
                    self.current_level.remove_sprite(self.body_flash_sprite)
                    self.body_flash_sprite = None
                self.body_is_flashing = False
                self.flash_count = 0
                self.flash_tick = 0
                self.is_reversing = True

    def update_goal_contacts(self) -> None:
        """"""
        for color_key, contact_state in self.goal_contact_map.items():
            goal_sprite = contact_state["goal"]
            body = self.robot_group_map[color_key]["body"]
            if not body and self.composite_body_map:
                body = self.find_body_matching_goal(goal_sprite)
            if not goal_sprite:
                continue
            is_colliding = body is not None and body.collides_with(goal_sprite)
            was_in_contact = contact_state["in_contact"]
            if is_colliding and (not was_in_contact) and (not contact_state["is_animating"]):
                contact_state["is_animating"] = True
                contact_state["contact_count"] = 0
                contact_state["anim_tick"] = 0
                contact_state["in_contact"] = True
            elif not is_colliding and was_in_contact:
                if contact_state["flash_sprite"] is not None:
                    self.current_level.remove_sprite(contact_state["flash_sprite"])
                    contact_state["flash_sprite"] = None
                contact_state["in_contact"] = False
                contact_state["is_animating"] = False
            if contact_state["is_animating"]:
                contact_state["anim_tick"] += 1
                if contact_state["anim_tick"] % 2 == 0:
                    show_flash = contact_state["anim_tick"] // 2 % 2 == 1
                    if show_flash:
                        if contact_state["flash_sprite"] is None:
                            new_flash_spr = sprites["flash-goal"].clone()
                            contact_state["flash_sprite"] = new_flash_spr
                            new_flash_spr.set_position(goal_sprite.x, goal_sprite.y)
                            self.current_level.add_sprite(new_flash_spr)
                    elif contact_state["flash_sprite"] is not None:
                        self.current_level.remove_sprite(contact_state["flash_sprite"])
                        contact_state["flash_sprite"] = None
                if contact_state["anim_tick"] % 4 == 0:
                    contact_state["contact_count"] += 1
                    if contact_state["contact_count"] >= 5:
                        if contact_state["flash_sprite"] is None:
                            new_flash_spr = sprites["flash-goal"].clone()
                            contact_state["flash_sprite"] = new_flash_spr
                            new_flash_spr.set_position(goal_sprite.x, goal_sprite.y)
                            self.current_level.add_sprite(new_flash_spr)
                        contact_state["is_animating"] = False

    def update_animation(self) -> None:
        """"""
        if not self.is_animating or not self.selected_leg:
            return
        self.update_goal_contacts()
        if self.body_is_flashing:
            self.update_body_flash()
            return
        if self.winning:
            all_done = True
            for color_key, contact_state in self.goal_contact_map.items():
                if contact_state["is_animating"]:
                    all_done = False
                    break
            if all_done:
                self.next_level()
                self.is_animating = False
                self.winning = False
            return
        if self.bounce_back:
            any_animating = any((contact_state["is_animating"] for contact_state in self.goal_contact_map.values()))
            if not any_animating:
                self.is_animating = False
                self.bounce_back = False
                self.complete_action()
            return
        if not self.is_reversing:
            self.anim_tick += 1
            anim_frac = self.anim_tick / self.anim_speed
            start_x, start_y = self.anim_start_pos
            end_x, end_y = self.anim_end_pos
            interp_x = int(start_x + (end_x - start_x) * anim_frac)
            interp_y = int(start_y + (end_y - start_y) * anim_frac)
            self.selected_leg.set_position(interp_x, interp_y)
            leg_color_key = self.get_color_key_for_leg(self.selected_leg)
            if leg_color_key and leg_color_key in self.robot_group_map:
                body = self.robot_group_map[leg_color_key]["body"]
                legs = self.robot_group_map[leg_color_key]["legs"]
                if body and legs:
                    self.center_body_on_legs(body, legs)
            if self.decoration_sprites:
                self.check_decoration_collisions()


            wall_sprite_list = [s for s in self.current_level.get_sprites() if s.name.startswith("wall-")]
            hit_wall_flag = False
            hit_body = None
            for color_key, data in self.robot_group_map.items():
                body = data["body"]
                if not body:
                    continue
                for wall_spr2 in wall_sprite_list:
                    if body.collides_with(wall_spr2):
                        hit_wall_flag = True
                        hit_body = body
                        break
                if hit_wall_flag:
                    break
            if hit_wall_flag and self.anim_tick >= self.anim_speed:
                self.wall_hit_count += 1
                if self.wall_hit_count >= 5:
                    self.lose()
                    self.is_animating = False
                    self.is_reversing = False
                    return
                self.body_is_flashing = True
                self.flash_count = 0
                self.flash_tick = 0
                self.flashing_body = hit_body
            elif self.anim_tick >= self.anim_speed:
                all_on_goal = True
                for color_key, data in self.robot_group_map.items():
                    body = data["body"]
                    goal_sprite = data["goal"]

                    if not goal_sprite or "target" in color_key:
                        continue
                    if body and goal_sprite:
                        if not body.collides_with(goal_sprite):
                            all_on_goal = False
                            break
                    else:
                        composite_on_goal = False
                        for body_name in self.composite_body_map.keys():
                            body_sprites = self.current_level.get_sprites_by_name(body_name)
                            if not body_sprites:
                                continue
                            composite_body = body_sprites[0]
                            if composite_body.collides_with(goal_sprite) and self.colors_match(composite_body, goal_sprite):
                                composite_on_goal = True
                                break
                        if not composite_on_goal:
                            all_on_goal = False
                            break
                if all_on_goal:
                    self.winning = True
                else:
                    self.bounce_back = True
        else:
            self.anim_tick -= 1
            anim_frac = self.anim_tick / self.anim_speed
            start_x, start_y = self.anim_start_pos
            end_x, end_y = self.anim_end_pos
            interp_x = int(start_x + (end_x - start_x) * anim_frac)
            interp_y = int(start_y + (end_y - start_y) * anim_frac)
            self.selected_leg.set_position(interp_x, interp_y)
            leg_color_key = self.get_color_key_for_leg(self.selected_leg)
            if leg_color_key and leg_color_key in self.robot_group_map:
                body = self.robot_group_map[leg_color_key]["body"]
                legs = self.robot_group_map[leg_color_key]["legs"]
                if body and legs:
                    self.center_body_on_legs(body, legs)
            if self.anim_tick <= 0:
                self.is_animating = False
                self.is_reversing = False
                self.complete_action()

    def step(self) -> None:
        """









        """

        self._step_log    = []
        self._step_log_l2 = []

        if not self._frame_action_logs:
            self._wall_hit_this_action     = 0
            self._wall_hit_target_name     = ""
            self._wall_hit_target_pos      = None
            self._goal_contact_this_action = set()
            self._goal_contact_pos         = {}
            self._win_pending              = False
            self._gameover_pending         = False






            self._prev_body_flash_visible  = self.body_flash_sprite is not None
            self._prev_goal_flash_visible  = {
                color_key: (state.get("flash_sprite") is not None)
                for color_key, state in self.goal_contact_map.items()
            }



        _before_sprites = {
            id(spr): {
                "name": spr.name,
                "x": spr.x, "y": spr.y,
                "width": spr.width, "height": spr.height,
                "rotation": spr.rotation,
                "visible": spr.is_visible,
            }
            for spr in self.current_level.get_sprites()
        }
        _before_hits = self.wall_hit_count
        _before_remaining = self._max_actions - self._action_count


        remaining_actions = self._max_actions - self._action_count
        self._step_counter_ui.set_current_steps(remaining_actions)
        if self._action_count >= self._max_actions:
            self.lose()
            self.complete_action()

            self._gameover_pending = True
            self._frame_sprite_log.append(self.get_sprite_status())
            self._frame_nonsprite_log.append(self.get_nonsprite_status())
            self._log_state.snapshot_step()
            self._finalize_action_log()
            return
        action = self.action
        if self.is_animating:
            self.update_animation()
            if not self.is_animating:
                self.complete_action()

            self._collect_diff_logs(_before_sprites, _before_hits, _before_remaining)
            self._frame_sprite_log.append(self.get_sprite_status())
            self._frame_nonsprite_log.append(self.get_nonsprite_status())
            self._log_state.snapshot_step()
            if self.is_action_complete():
                self._finalize_action_log()
            return
        if action.id == GameAction.ACTION6:
            click_x = action.data.get("x", 0)
            click_y = action.data.get("y", 0)
            grid_pos = self.camera.display_to_grid(click_x, click_y)
            if grid_pos:
                gx, gy = grid_pos
                clicked_leg = None
                for i, leg in enumerate(self.all_legs):
                    if leg.x <= gx < leg.x + leg.width and leg.y <= gy < leg.y + leg.height:
                        clicked_leg = leg
                        self.selected_leg_idx = i
                        break
                if clicked_leg:


                    prev_selected = self.selected_leg
                    self.select_leg(clicked_leg)
                    if prev_selected is not clicked_leg:


                        if prev_selected is not None:
                            _pdx, _pdy, _pdw, _pdh = self._to_display_bbox(prev_selected)
                            _pt, _ple, _pl2 = self._display_for(prev_selected)
                            self._step_log.append(f"[bright]:[{_pt}]:[sname({prev_selected.name});position({_pdx}_{_pdy});bbox({_pdw}_{_pdh});state(off)]:{_ple} at ({_pdx},{_pdy}) is deselected and its highlight turns off.|Object at ({_pdx},{_pdy}) is unhighlighted.")
                            self._step_log_l2.append(f"[bright]:[{_pt}]:[sname({prev_selected.name});position({_pdx}_{_pdy});bbox({_pdw}_{_pdh});state(off)]:({_pdx},{_pdy}){_pl2}|({_pdx},{_pdy})Object")
                        _ldx, _ldy, _ldw, _ldh = self._to_display_bbox(clicked_leg)
                        _ct, _cle, _cl2 = self._display_for(clicked_leg)
                        self._step_log.append(f"[bright]:[{_ct}]:[sname({clicked_leg.name});position({_ldx}_{_ldy});bbox({_ldw}_{_ldh});state(selected)]:{_cle} at ({_ldx},{_ldy}) is selected (highlighted) on click.|Object at ({_ldx},{_ldy}) is highlighted.")
                        self._step_log_l2.append(f"[bright]:[{_ct}]:[sname({clicked_leg.name});position({_ldx}_{_ldy});bbox({_ldw}_{_ldh});state(selected)]:({_ldx},{_ldy}){_cl2}|({_ldx},{_ldy})Object")
                    self.complete_action()
                elif self.selected_leg:
                    half_w = self.selected_leg.width // 2
                    half_h = self.selected_leg.height // 2
                    target_x = gx - half_w
                    target_y = gy - half_h
                    if not self.would_collide_with_wall(target_x, target_y):

                        self.start_move_animation(target_x, target_y)
                        self._collect_diff_logs(_before_sprites, _before_hits, _before_remaining)
                        self._frame_sprite_log.append(self.get_sprite_status())
                        self._frame_nonsprite_log.append(self.get_nonsprite_status())
                        self._log_state.snapshot_step()
                        return
                    else:
                        tdx, tdy = self._to_display_xy(target_x, target_y)
                        _sdx, _sdy, _sdw, _sdh = self._to_display_bbox(self.selected_leg)
                        _t, _le, _l2 = self._display_for(self.selected_leg)
                        self._step_log.append(f"[bright]:[{_t}]:[sname({self.selected_leg.name});position({_sdx}_{_sdy});bbox({_sdw}_{_sdh});state(flash)]:{_le} at ({_sdx},{_sdy}) flashes to indicate the move to ({tdx},{tdy}) is blocked by a wall.|Object at ({_sdx},{_sdy}) flashes.")
                        self._step_log_l2.append(f"[bright]:[{_t}]:[sname({self.selected_leg.name});position({_sdx}_{_sdy});bbox({_sdw}_{_sdh});state(flash)]:({_sdx},{_sdy}){_l2}({tdx},{tdy})|({_sdx},{_sdy})Object")
                        self.complete_action()
                else:
                    self.complete_action()
            else:
                self.complete_action()
            self._collect_diff_logs(_before_sprites, _before_hits, _before_remaining)
            self._frame_sprite_log.append(self.get_sprite_status())
            self._frame_nonsprite_log.append(self.get_nonsprite_status())
            self._log_state.snapshot_step()
            if self.is_action_complete():
                self._finalize_action_log()
            return
        self.complete_action()
        self._collect_diff_logs(_before_sprites, _before_hits, _before_remaining)
        self._frame_sprite_log.append(self.get_sprite_status())
        self._frame_nonsprite_log.append(self.get_nonsprite_status())
        self._log_state.snapshot_step()
        if self.is_action_complete():
            self._finalize_action_log()

    def _set_event(self, key: str, value) -> None:
        """

        """
        if hasattr(self, "_log_state") and self._log_state is not None:
            self._log_state.set_event(key, value)

    def _display_for(self, spr_or_name) -> tuple[str, str, str]:
        """







        """
        if isinstance(spr_or_name, str):
            return SPRITE_DISPLAY.get(spr_or_name, (spr_or_name, spr_or_name, spr_or_name))
        return _label_for_sprite(spr_or_name)

    def _to_display_xy(self, x: int, y: int) -> tuple[int, int]:
        """



        """
        cam = self.camera
        arc_scale = min(64 // cam.width, 64 // cam.height)
        x_off = (64 - cam.width  * arc_scale) // 2
        y_off = (64 - cam.height * arc_scale) // 2
        return (x - cam.x) * arc_scale + x_off, (y - cam.y) * arc_scale + y_off


    def _to_display_bbox(self, spr) -> tuple[int, int, int, int]:
        """

        """
        cam = self.camera
        arc_scale = min(64 // cam.width, 64 // cam.height)
        x_off = (64 - cam.width  * arc_scale) // 2
        y_off = (64 - cam.height * arc_scale) // 2
        dx = (spr.x - cam.x) * arc_scale + x_off
        dy = (spr.y - cam.y) * arc_scale + y_off
        dw = spr.width  * arc_scale
        dh = spr.height * arc_scale
        return dx, dy, dw, dh

    def _finalize_action_log(self) -> None:
        """








        """
        import re
        _RE_POS = re.compile(
            r'(\[.+?\]):\[(.+?)\]:\[([^\]]*?)position\((-?\d+)_(-?\d+)\)_\((-?\d+)_(-?\d+)\)([^\]]*)\]:(.*)')


        _FRAME_ONLY_PREFIXES = (
            "[bright]:[flash-robot_body]:",
            "[bright]:[flash-goal]:",
        )

        seen_en: set[str] = set()
        move_chain_idx: dict[str, int] = {}
        result_en: list[str] = []
        result_l2: list[str] = []

        all_en = [e for fr in self._frame_action_logs    for e in fr]
        all_l2 = [e for fr in self._frame_action_logs_l2 for e in fr]

        def _sign(n: int) -> int:
            return 0 if n == 0 else (1 if n > 0 else -1)

        for en, l2 in zip(all_en, all_l2):
            if any(en.startswith(p) for p in _FRAME_ONLY_PREFIXES):
                continue
            m = _RE_POS.fullmatch(en)
            if m and m.group(1) == "[move]":
                tgt = m.group(2)
                cur_x1, cur_y1 = int(m.group(4)), int(m.group(5))
                x2, y2         = int(m.group(6)), int(m.group(7))
                if tgt in move_chain_idx:

                    idx = move_chain_idx[tgt]
                    prev_en = result_en[idx]
                    prev_m = _RE_POS.fullmatch(prev_en)
                    if prev_m:
                        x1, y1         = int(prev_m.group(4)), int(prev_m.group(5))
                        prev_x2, prev_y2 = int(prev_m.group(6)), int(prev_m.group(7))



                        prev_dir = (_sign(prev_x2 - x1),     _sign(prev_y2 - y1))
                        cur_dir  = (_sign(x2 - cur_x1),      _sign(y2 - cur_y1))
                        dir_change = (
                            prev_dir != (0, 0) and cur_dir != (0, 0)
                            and prev_dir != cur_dir
                        )
                        if dir_change:
                            move_chain_idx[tgt] = len(result_en)
                            result_en.append(en)
                            result_l2.append(l2)
                            continue




                        new_params = prev_m.group(3) + f"position({x1}_{y1})_({x2}_{y2})" + prev_m.group(8)
                        _sname_m = re.search(r'sname\(([^)]+)\)', new_params)
                        _src_name = _sname_m.group(1) if _sname_m else tgt
                        _, _le, _l2 = self._display_for(_src_name)
                        new_en = f"[move]:[{tgt}]:[{new_params}]:{_le} moves from ({x1},{y1}) to ({x2},{y2}).|Object moves from ({x1},{y1}) to ({x2},{y2})."
                        new_l2 = f"[move]:[{tgt}]:[{new_params}]:{_l2}({x1},{y1})({x2},{y2})|Object({x1},{y1})({x2},{y2})"
                        result_en[idx] = new_en
                        result_l2[idx] = new_l2
                    continue
                else:
                    move_chain_idx[tgt] = len(result_en)
                    result_en.append(en)
                    result_l2.append(l2)
                    continue

            if en in seen_en:
                continue
            seen_en.add(en)
            result_en.append(en)
            result_l2.append(l2)




        if self._wall_hit_this_action > 0 and self._wall_hit_target_pos is not None:
            wx, wy, ww, wh = self._wall_hit_target_pos
            _wt, _wle, _wl2 = self._display_for(self._wall_hit_target_name)
            result_en.append(
                f"[bright]:[{_wt}]:[sname({self._wall_hit_target_name});position({wx}_{wy});bbox({ww}_{wh});state(wall_hit)]:"
                f"{_wle} at ({wx},{wy}) hits a wall and the body flashes.|Object at ({wx},{wy}) flashes."
            )
            result_l2.append(
                f"[bright]:[{_wt}]:[sname({self._wall_hit_target_name});position({wx}_{wy});bbox({ww}_{wh});state(wall_hit)]:"
                f"({wx},{wy}){_wl2}|({wx},{wy})Object"
            )


        for color_key in self._goal_contact_this_action:
            pos = self._goal_contact_pos.get(color_key)
            if pos is None:
                continue
            gx, gy, gw, gh = pos

            _goal_sprite_name = f"goal-{color_key}"
            _, _gle, _gl2 = self._display_for(_goal_sprite_name)
            result_en.append(
                f"[bright]:[goal]:[sname({_goal_sprite_name});position({gx}_{gy});bbox({gw}_{gh});state(contact)]:"
                f"A robot body reaches {_gle} and the goal flashes."
                f"|An Object reaches an Object and flashes."
            )
            result_l2.append(
                f"[bright]:[goal]:[sname({_goal_sprite_name});position({gx}_{gy});bbox({gw}_{gh});state(contact)]:"
                f"{_gl2}"
                f"|ObjectObject"
            )


        if self._win_pending:
            result_en.append("[win]:[game]:[]:The level is cleared.|The level is cleared.")
            result_l2.append("[win]:[game]:[]:|")
        if self._gameover_pending:
            result_en.append("[gameover]:[game]:[]:Step limit reached, game over.|Game over.")
            result_l2.append("[gameover]:[game]:[]:|")






        _layout_rows = self._log_state.get_event("initial_layout") if self._log_state else None
        if _layout_rows:
            for r in _layout_rows:
                role    = r["role"]
                sname   = r["sname"]
                dx, dy  = r["dx"], r["dy"]
                dw, dh  = r["dw"], r["dh"]
                role_en = r.get("role_en") or " ".join(w.capitalize() for w in role.split("_"))
                role_l2 = r.get("role_l2") or role_en
                params  = f"sname({sname});position({dx}_{dy});bbox({dw}_{dh})"
                result_en.append(
                    f"[layout]:[{role}]:[{params}]:"
                    f"{role_en} is placed at ({dx},{dy}).|Object is placed at ({dx},{dy})."
                )
                result_l2.append(
                    f"[layout]:[{role}]:[{params}]:"
                    f"{role_l2}({dx},{dy})|Object({dx},{dy})"
                )

        self.action_log    = result_en
        self.action_log_l2 = result_l2

    def _bar_pixel_len(self, value: int) -> int:
        """



        """
        height = 64
        max_steps = self._step_counter_ui.max_steps
        if max_steps == 0:
            return 0
        ratio = value / max_steps
        filled = round(height * ratio)
        return min(filled, height)

    def _collect_diff_logs(self, before_sprites: dict, _before_hits: int, _before_remaining: int) -> None:
        """



        """
        after_sprites = {id(spr): spr for spr in self.current_level.get_sprites()}


        for spr_id, spr in after_sprites.items():
            if spr.name in _APPEAR_SUPPRESS:
                continue
            b = before_sprites.get(spr_id)
            if b is None or (not b["visible"] and spr.is_visible):
                dx, dy, dw, dh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr)
                self._step_log.append(f"[appear]:[{_t}]:[sname({spr.name});position({dx}_{dy});bbox({dw}_{dh})]:{_le} appears at ({dx},{dy}).|Object appears at ({dx},{dy}).")
                self._step_log_l2.append(f"[appear]:[{_t}]:[sname({spr.name});position({dx}_{dy});bbox({dw}_{dh})]:{_l2}({dx},{dy})|Object({dx},{dy})")



        _arc_scale_d = min(64 // self.camera.width, 64 // self.camera.height)
        for spr_id, b in before_sprites.items():
            if b["name"] in _APPEAR_SUPPRESS:
                continue
            spr = after_sprites.get(spr_id)
            gone = spr is None and b["visible"]
            hid  = spr is not None and b["visible"] and not spr.is_visible
            if gone or hid:
                bdx, bdy = self._to_display_xy(b["x"], b["y"])
                bdw = int(b.get("width", 0))  * _arc_scale_d
                bdh = int(b.get("height", 0)) * _arc_scale_d
                _t, _le, _l2 = self._display_for(b['name'])
                self._step_log.append(f"[disappear]:[{_t}]:[sname({b['name']});position({bdx}_{bdy});bbox({bdw}_{bdh})]:{_le} disappears from ({bdx},{bdy}).|Object disappears from ({bdx},{bdy}).")
                self._step_log_l2.append(f"[disappear]:[{_t}]:[sname({b['name']});position({bdx}_{bdy});bbox({bdw}_{bdh})]:{_l2}({bdx},{bdy})|Object({bdx},{bdy})")


        for spr_id, spr in after_sprites.items():
            if not spr.is_visible:
                continue
            b = before_sprites.get(spr_id)
            if b is None or not b["visible"]:
                continue
            if (spr.x, spr.y) != (b["x"], b["y"]):
                bdx, bdy = self._to_display_xy(b["x"], b["y"])
                adx, ady, adw, adh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr)
                self._step_log.append(f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:{_le} moves from ({bdx},{bdy}) to ({adx},{ady}).|Object moves from ({bdx},{bdy}) to ({adx},{ady}).")
                self._step_log_l2.append(f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:{_l2}({bdx},{bdy})({adx},{ady})|Object({bdx},{bdy})({adx},{ady})")
            if spr.rotation != b["rotation"]:
                _rdx, _rdy, _rdw, _rdh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr)
                self._step_log.append(f"[rotate]:[{_t}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b['rotation']})_({spr.rotation})]:{_le} at ({_rdx},{_rdy}) rotates from {b['rotation']}° to {spr.rotation}°.|Object at ({_rdx},{_rdy}) rotates from {b['rotation']}° to {spr.rotation}°.")
                self._step_log_l2.append(f"[rotate]:[{_t}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b['rotation']})_({spr.rotation})]:({_rdx},{_rdy}){_l2}{b['rotation']}°{spr.rotation}°|({_rdx},{_rdy})Object{b['rotation']}°{spr.rotation}°")

        if self.wall_hit_count != _before_hits:




            self._step_log.append(f"[change]:[wall_hit_count]:[count({_before_hits})_({self.wall_hit_count})]:The wall-hit counter increases from {_before_hits} to {self.wall_hit_count}.|The counter increases from {_before_hits} to {self.wall_hit_count}.")
            self._step_log_l2.append(f"[change]:[wall_hit_count]:[count({_before_hits})_({self.wall_hit_count})]:{_before_hits}{self.wall_hit_count}|{_before_hits}{self.wall_hit_count}")




        remaining_now  = self._max_actions - self._action_count
        before_for_log = self._max_actions - self._last_logged_action_count
        if remaining_now != before_for_log and self._bar_pixel_len(before_for_log) != self._bar_pixel_len(remaining_now):
            self._last_logged_action_count = self._action_count
            if remaining_now < before_for_log:
                self._step_log.append(f"[change]:[steps]:[sname(step_counter);count({before_for_log})_({remaining_now})]:The white step bar on the left edge shrinks from the top ({before_for_log}→{remaining_now} steps remain).|The white Object on the left edge shrinks from the top ({before_for_log}→{remaining_now}).")
                self._step_log_l2.append(f"[change]:[steps]:[sname(step_counter);count({before_for_log})_({remaining_now})]:{before_for_log}→{remaining_now}|Object{before_for_log}→{remaining_now}")
            else:
                self._step_log.append(f"[change]:[steps]:[sname(step_counter);count({before_for_log})_({remaining_now})]:The white step bar on the left edge extends to the top ({before_for_log}→{remaining_now} steps).|The white Object on the left edge extends to the top ({before_for_log}→{remaining_now}).")
                self._step_log_l2.append(f"[change]:[steps]:[sname(step_counter);count({before_for_log})_({remaining_now})]:{before_for_log}→{remaining_now}|Object{before_for_log}→{remaining_now}")



        body_flash_visible = self.body_flash_sprite is not None
        if body_flash_visible != self._prev_body_flash_visible:
            if self.flashing_body is not None:
                fdx, fdy, fdw, fdh = self._to_display_bbox(self.flashing_body)
                if body_flash_visible:
                    _ft, _fle, _fl2 = self._display_for(self.flashing_body)
                    self._step_log.append(f"[bright]:[flash_robot_body]:[sname(flash-robot_body);position({fdx}_{fdy});bbox({fdw}_{fdh});state(flash)]:A flash sprite appears over {_fle}.|A flash sprite appears over an Object.")
                    self._step_log_l2.append(f"[bright]:[flash_robot_body]:[sname(flash-robot_body);position({fdx}_{fdy});bbox({fdw}_{fdh});state(flash)]:{_fl2}|Object")
                else:
                    _ft, _fle, _fl2 = self._display_for(self.flashing_body)
                    self._step_log.append(f"[bright]:[flash_robot_body]:[sname(flash-robot_body);position({fdx}_{fdy});bbox({fdw}_{fdh});state(off)]:The flash sprite over {_fle} disappears between blinks.|The flash sprite over an Object disappears between blinks.")
                    self._step_log_l2.append(f"[bright]:[flash_robot_body]:[sname(flash-robot_body);position({fdx}_{fdy});bbox({fdw}_{fdh});state(off)]:{_fl2}|Object")
        self._prev_body_flash_visible = body_flash_visible
        if self.body_is_flashing and self.flashing_body is not None:
            self._wall_hit_target_name = self.flashing_body.name
            self._wall_hit_target_pos  = self._to_display_bbox(self.flashing_body)
            self._wall_hit_this_action = max(self._wall_hit_this_action, 1)


        for color_key, contact_state in self.goal_contact_map.items():
            curr_visible = contact_state.get("flash_sprite") is not None
            prev_visible = self._prev_goal_flash_visible.get(color_key, False)
            if curr_visible != prev_visible:
                goal_sprite = contact_state.get("goal")
                if goal_sprite is not None:
                    gdx, gdy, gdw, gdh = self._to_display_bbox(goal_sprite)
                    if curr_visible:
                        self._step_log.append(f"[bright]:[flash_goal]:[sname(flash-goal);position({gdx}_{gdy});bbox({gdw}_{gdh});state(flash)]:A flash sprite appears over a Goal.|A flash sprite appears over an Object.")
                        self._step_log_l2.append(f"[bright]:[flash_goal]:[sname(flash-goal);position({gdx}_{gdy});bbox({gdw}_{gdh});state(flash)]:|Object")
                    else:
                        self._step_log.append(f"[bright]:[flash_goal]:[sname(flash-goal);position({gdx}_{gdy});bbox({gdw}_{gdh});state(off)]:The flash sprite over a Goal disappears between blinks.|The flash sprite over an Object disappears between blinks.")
                        self._step_log_l2.append(f"[bright]:[flash_goal]:[sname(flash-goal);position({gdx}_{gdy});bbox({gdw}_{gdh});state(off)]:|Object")
            self._prev_goal_flash_visible[color_key] = curr_visible
            if contact_state.get("is_animating"):
                goal_sprite = contact_state.get("goal")
                if goal_sprite is not None:
                    self._goal_contact_this_action.add(color_key)
                    self._goal_contact_pos[color_key] = self._to_display_bbox(goal_sprite)




        if self.winning:
            self._win_pending = True






    @property
    def _step_log(self) -> list[str]:
        return self._log_state._step_log
    @_step_log.setter
    def _step_log(self, value: list[str]) -> None:
        self._log_state._step_log = value

    @property
    def _step_log_l2(self) -> list[str]:
        return self._log_state._step_log_l2
    @_step_log_l2.setter
    def _step_log_l2(self, value: list[str]) -> None:
        self._log_state._step_log_l2 = value

    @property
    def _frame_action_logs(self) -> list[list[str]]:
        return self._log_state._frames
    @_frame_action_logs.setter
    def _frame_action_logs(self, value: list[list[str]]) -> None:
        self._log_state._frames = value

    @property
    def _frame_action_logs_l2(self) -> list[list[str]]:
        return self._log_state._frames_l2
    @_frame_action_logs_l2.setter
    def _frame_action_logs_l2(self, value: list[list[str]]) -> None:
        self._log_state._frames_l2 = value

    def reset_logs(self) -> None:
        """

        """
        self._log_state.reset()
        self.action_log    = []
        self.action_log_l2 = []

    def get_action_log_frame(self) -> tuple[list[list[str]], list[list[str]]]:
        return self._log_state.get_frame_logs()

    def get_action_log(self) -> tuple[list[str], list[str]]:
        """




        """
        self._finalize_action_log()
        en, l2 = list(self.action_log), list(self.action_log_l2)
        reset_evt = self._log_state.get_event("reset")
        if reset_evt:
            r_en = reset_evt.get("en", "[reset]:[game]:[]:The game state is reset.") \
                if isinstance(reset_evt, dict) else "[reset]:[game]:[]:The game state is reset."
            r_l2 = reset_evt.get("l2", "[reset]:[game]:[]:") \
                if isinstance(reset_evt, dict) else "[reset]:[game]:[]:"
            en.insert(0, r_en)
            l2.insert(0, r_l2)
        return en, l2

    def get_sprite_status(self) -> list[dict]:
        """










        """
        result = []
        for spr in self.current_level.get_sprites():
            if not spr.is_visible:
                continue
            tags     = list(spr._tags) if spr._tags else []



            _t, _le, _l2 = _label_for_sprite(spr)
            if _le != spr.name:

                label, label_l2 = _le, _l2
            else:

                label    = next((TAG_DISPLAY_NAMES[t]    for t in tags if t in TAG_DISPLAY_NAMES),    spr.name)
                label_l2 = next((TAG_DISPLAY_NAMES_L2[t] for t in tags if t in TAG_DISPLAY_NAMES_L2), spr.name)
            result.append({
                "spr_id":   id(spr),
                "name":     spr.name,
                "label":    label,
                "label_l2": label_l2,
                "tags":     tags,
                "x":        spr.x,
                "y":        spr.y,
                "width":    spr.width,
                "height":   spr.height,
                "rotation": spr.rotation,
            })
        return result

    def get_nonsprite_status(self) -> list[dict]:
        """


        """
        remaining = max(0, self._max_actions - self._action_count)
        return [
            {
                "name":     "step_counter",
                "label":    "Steps Remaining",
                "label_l2": ''            ,
                "value":    remaining,
                "max":      self._max_actions,
                "x":        0, "y": 0,
                "width":    1, "height": 64,
            },
        ]

    def get_game_knowledge(self) -> dict:
        """


        """
        return GAME_KNOWLEDGE
